export function makeGitHubFileContentsResponse() {
  const sampleCode = [
    'import { Server } from "@modelcontextprotocol/sdk/server/index.js";',
    "",
    "export class GitHubService {",
    "  constructor(token, baseUrl = 'https://api.github.com') {",
    "    this.token = token;",
    "    this.baseUrl = baseUrl;",
    "  }",
    "",
    "  async getRepository(owner, repo) {",
    "    const response = await fetch(`${this.baseUrl}/repos/${owner}/${repo}`);",
    "    return response.json();",
    "  }",
    "",
    "  async listPullRequests(owner, repo, state = 'open') {",
    "    const response = await fetch(`${this.baseUrl}/repos/${owner}/${repo}/pulls?state=${state}`);",
    "    return response.json();",
    "  }",
    "}",
    "",
    "export function validateConfig(cfg) {",
    "  if (!cfg || !cfg.token) throw new Error('Missing token');",
    "  return true;",
    "}",
  ].join("\n");

  const fullCode = Array.from({ length: 15 }, (_, i) => `// Section ${i + 1}\n${sampleCode}`).join("\n\n");
  const base64Content = Buffer.from(fullCode, "utf-8").toString("base64");

  return {
    name: "service.js",
    path: "src/service.js",
    sha: "3d21ec53a331a6f037a91c368710b99387d012c1",
    size: Buffer.byteLength(fullCode, "utf-8"),
    url: "https://api.github.com/repos/octocat/Hello-World/contents/src/service.js?ref=main",
    html_url: "https://github.com/octocat/Hello-World/blob/main/src/service.js",
    git_url: "https://api.github.com/repos/octocat/Hello-World/git/blobs/3d21ec53a331a6f037a91c368710b99387d012c1",
    download_url: "https://raw.githubusercontent.com/octocat/Hello-World/main/src/service.js",
    type: "file",
    content: base64Content,
    encoding: "base64",
    _links: {
      self: "https://api.github.com/repos/octocat/Hello-World/contents/src/service.js?ref=main",
      git: "https://api.github.com/repos/octocat/Hello-World/git/blobs/3d21ec53a331a6f037a91c368710b99387d012c1",
      html: "https://github.com/octocat/Hello-World/blob/main/src/service.js",
    },
  };
}
